const cartAvailable=p=>p.active!==false&&Number(p.price)>0;const shop=WildRideShop,api=WildRideMember,host=document.getElementById('cart-items'),message=document.getElementById('ops-status');let requestKey=crypto.randomUUID();function say(t,error=false){message.textContent=t;message.classList.toggle('error',error)}function el(tag,t,cls){const e=document.createElement(tag);if(t)e.textContent=t;if(cls)e.className=cls;return e}async function render(){const items=await shop.items();host.replaceChildren();for(const p of items){const row=el('article',null,'ops-row'),img=el('img');img.src=p.image;img.alt=p.name;const body=el('div',null,'grow');body.append(el('b',p.name),el('small',(p.demo?'AI 示意・':'')+(cartAvailable(p)?'NT$'+p.price.toLocaleString():'未上架，請移除後再送出')));const qty=el('input');qty.type='number';qty.min=1;qty.max=20;qty.value=p.quantity;qty.disabled=!cartAvailable(p);qty.setAttribute('aria-label',p.name+'數量');qty.addEventListener('change',()=>act(async()=>{const n=Number(qty.value);if(!Number.isInteger(n)||n<1||n>20)throw Error('數量需為 1–20。');await shop.set(p.id,n);requestKey=crypto.randomUUID();await render()}));const remove=el('button','移除');remove.onclick=()=>act(async()=>{await shop.set(p.id,0);requestKey=crypto.randomUUID();await render()});row.append(img,body,qty,remove);host.append(row)}if(!items.length)host.append(el('p','購物車還沒有商品，先到馭野嚴選看看。'));document.getElementById('cart-total').textContent='商品參考合計 NT$'+items.reduce((n,p)=>n+p.price*p.quantity,0).toLocaleString();document.getElementById('checkout').disabled=!items.length||!shop.member||items.some(p=>!cartAvailable(p));document.getElementById('merge-guest').hidden=!shop.member||!shop.hasGuest();document.getElementById('cart-auth').hidden=!!shop.member}async function act(fn){try{await fn()}catch(e){say(e.message,true)}}document.getElementById('merge-guest').onclick=()=>act(async()=>{await shop.merge();await render();say('訪客購物車已合併至目前會員。')});document.getElementById('checkout-form').onsubmit=e=>{e.preventDefault();const b=document.getElementById('checkout');b.disabled=true;act(async()=>{try{const current=await shop.items();if(current.some(p=>!cartAvailable(p)))throw Error('購物車有未上架商品，請移除後再送出。');const r=await api.request('checkout',{requestKey,note:document.getElementById('order-note').value});document.getElementById('order-result').textContent='已建立'+(r.order.kind==='inquiry'?'詢價':'預約')+'單：'+r.order.id+'。可至會員中心查看，未收取任何款項。';requestKey=crypto.randomUUID();await render();say('已送出，等待學院確認。')}finally{await render()}})};shop.init().then(render).catch(e=>say(e.message,true));
